      const origText = btn ? btn.innerText : 'Submit';
      const endpoint = 'https://api.formdock.in/api/v1/public/forms/submit/';
      const apiKey = form.getAttribute('data-project-api-key');
      const successEl = form.querySelector('.form-success-banner');
      const errorEl = form.querySelector('.form-error-banner');

      if (successEl) successEl.style.display = 'none';
      if (errorEl) errorEl.style.display = 'none';
      if (!apiKey) {
        if (errorEl) {
          errorEl.textContent = 'This form is not connected yet. Add your Formdock public API key in the editor.';
          errorEl.style.display = 'block';
        }
        return;
      }

